$ErrorActionPreference = 'Stop'
$jsPath = Join-Path (Get-Location).Path '.bhmff-champions-patch.cjs'
$encoded = ''
[IO.File]::WriteAllBytes($jsPath, [Convert]::FromBase64String($encoded))
try {
    & node $jsPath
    if ($LASTEXITCODE -ne 0) { throw 'Patch failed; no source changes made.' }
} finally {
    Remove-Item $jsPath -Force -ErrorAction SilentlyContinue
}
